SELECT 
    *
FROM
    customer_shopping_behaviour.customer_data;

use customer_shopping_behaviour;

 -- Total revenue generated by male vs female customers x`
SELECT 
    gender, SUM(purchase_amount) AS revenue
FROM
    customer_data
GROUP BY gender;
 
 --  Which customers used a discount but still spent more than the average purhase amount?
SELECT 
    customer_id, purchase_amount
FROM
    customer_data
WHERE
    discount_applied = 'yes'
        AND purchase_amount >= (SELECT 
            AVG(purchase_amount)
        FROM
            customer_data);
 
 -- which are the top 5 products with the highest average review rating ?
SELECT 
    item_purchased,
    ROUND(AVG(review_rating), 2) AS avg_product_rating
FROM
    customer_data
GROUP BY item_purchased
ORDER BY Avg_product_rating DESC
LIMIT 5;
 
-- compare the average purchase amount between standard and exprss shipping 
SELECT 
    shipping_type,
    ROUND(AVG(purchase_amount), 2) AS avg_purchase_amount
FROM
    customer_data
WHERE
    shipping_type IN ('Standard' , 'Express')
GROUP BY shipping_type;
 
 -- Do subscribed customers spend more ? compare average spend and total revenue 
SELECT 
    subscription_status,
    COUNT(customer_id) AS Total_customers,
    ROUND(AVG(purchase_amount), 2) AS avg_spend,
    ROUND(SUM(purchase_amount), 2) AS total_revenue
FROM
    customer_data
GROUP BY subscription_status
ORDER BY total_revenue , avg_spend DESC;
 
 --  wich 5 products have the highest percentage of purchase with discount applied ?
SELECT 
    item_purchased,
    ROUND(100 * SUM(CASE
                WHEN discount_applied = 'Yes' THEN 1
                ELSE 0
            END) / COUNT(*),
            2) AS discounted_rate
FROM
    customer_data
GROUP BY item_purchased
ORDER BY discounted_rate DESC
LIMIT 5;
 
 -- segment customers into New, Returning and loyal based on their total
 -- number of previous purchases, and show the count of each segment.
 
 with customer_type as(
 select customer_id, previous_purchases,
 case
     when previous_purchases = 1 then 'New'
     when previous_purchases between 2 and 10 then 'returning'
     else 'loyal'
     end as customer_segment
from customer_data 
)

select customer_segment, count(*) as 'number of customers'
from customer_type
group by customer_segment;
 
 
-- What are the top 3 most purchased products within each category ?
 with item_counts as(
  select category,
  item_purchased,
  count(customer_id) as total_orders,
  row_number() over(partition by category order by count(customer_id) desc) as item_rank
  from customer_data
  group by category, item_purchased
 )
 
 select item_rank, category, item_purchased, total_orders
 from item_counts
 where item_rank <= 3;
 
 -- Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe ?
SELECT 
    subscription_status, COUNT(customer_id) AS repeat_buyers
FROM
    customer_data
WHERE
    previous_purchases > 5
GROUP BY subscription_status;
 
 -- What is the revenue contribution of each age group ?
SELECT 
    age_group, SUM(purchase_amount) AS total_revenue
FROM
    customer_data
GROUP BY age_group
ORDER BY total_revenue DESC;